<?php
use Illuminate\Support\Facades\{DB,Gate};
$retainOrientationFixtures=true;
require __DIR__.'/orientation-integration.php';
try {
Gate::define('modifier-courrier',fn($user)=>true);
if (!$existing) Illuminate\Support\Facades\Schema::create('courrier_reads',function($t){$t->string('courrier_id');$t->string('user_id');$t->timestamp('read_at');$t->unique(['courrier_id','user_id']);});
$policy=app(App\Services\AnnotationActionPolicy::class);
foreach ([$secretary,$director,$agent] as $person) check($policy->reason($person,$c)!==null,'non-DG cannot annotate: '.$person->role);
$c2=App\Models\Courrier::withoutEvents(fn()=>App\Models\Courrier::create(['type'=>'INTERNE','sens'=>'ENTRANT','date_reception'=>now(),'date_enregistrement'=>now(),'objet'=>'DG routing test','expediteur'=>'Test','destinataire'=>'Test','numero'=>uniqid('DG-'),'statut'=>'ASSIGNE','enregistre_par'=>$secDG->id,'priorite'=>'NORMALE']));
$plan=app(App\Services\OrganisationWorkflowService::class)->plan($dg,$c2,$unit->id,null,true);
check(!collect($plan)->contains('phase','SECRETARIAT'),'initial secretary check removed');
check(collect($plan)->first()['phase']==='ORIENTATION','DG is the first step');
check(!collect($plan)->contains('phase','VALIDATION'),'no visa in new circuits');
$source=App\Models\WorkflowEtape::create(['courrier_id'=>$c2->id,'etape'=>'DG','assigne_a'=>$dg->id,'cree_par'=>$dg->id,'statut'=>'EN_ATTENTE','ordre'=>1,'declencheur'=>['type'=>'IMMEDIAT','phase'=>'ORIENTATION']]);
$visa=App\Models\WorkflowEtape::create(['courrier_id'=>$c2->id,'etape'=>'Visa','assigne_a'=>$dg->id,'cree_par'=>$dg->id,'statut'=>'EN_ATTENTE','ordre'=>2,'declencheur'=>['type'=>'APRES_ETAPE','etapePrecedenteId'=>$source->id,'phase'=>'VALIDATION']]);
$a=App\Models\Annotation::create(['courrier_id'=>$c2->id,'created_by'=>$dg->id,'workflow_etape_id'=>$source->id,'contenu'=>'Instruction DG','type'=>'NOTE','fichier_id'=>'test']);
$router=app(App\Services\DgAnnotationRoutingService::class);
$router->route($dg,$c2,$a,['type'=>'ENTITE','id'=>$unit->id]);
check(App\Models\WorkflowEtape::where('courrier_id',$c2->id)->where('assigne_a',$secretary->id)->exists(),'internal destination passes through its secretariat');
$task=App\Models\WorkflowEtape::where('courrier_id',$c2->id)->where('assigne_a',$director->id)->firstOrFail();
check($task->declencheur['orientation']['annotationId']===$a->id,'entity target creates task with DG evidence');
check($visa->fresh()->declencheur['etapePrecedenteId']===$task->id,'final visa waits for target');
$router->route($dg,$c2,$a,['type'=>'ENTITE','id'=>$unit->id]);
check(App\Models\WorkflowEtape::where('courrier_id',$c2->id)->count()===4,'same target reuses secretariat and director tasks');
$router->route($dg,$c2,$a,['type'=>'USER','id'=>$agent->id]);
check(App\Models\WorkflowEtape::where('courrier_id',$c2->id)->where('assigne_a',$agent->id)->exists(),'specific user target creates task');
denied(fn()=>$router->route($director,$c2,$a,['type'=>'USER','id'=>$agent->id]),403);
App\Models\WorkflowEtape::whereKey($source->id)->update(['statut'=>'TERMINE','date_fin'=>now()]);
$engine=app(App\Services\WorkflowExecutionService::class);
app(App\Services\CourrierOrientationService::class)->orient($secretary,$c2->fresh(),['assigneA'=>$director->id]);
$engine->transition($task->id,$director,['statut'=>'EN_COURS'],false);
$engine->transition($task->id,$director,['statut'=>'TERMINE','commentaire'=>'Retour du directeur sans annotation'],false);
check($task->fresh()->statut==='TERMINE','non-DG completes task using return only');
$receipt=app(App\Services\CourrierOpeningReceiptService::class);
$count=App\Models\Notification::where('relatedId',$c2->id)->count();
$receipt->record($c2,$secretary);
check(App\Models\Notification::where('relatedId',$c2->id)->count()===$count,'secretariat opening does not acknowledge final receipt');
$receipt->record($c2,$director);
$ack=App\Models\Notification::where('relatedId',$c2->id)->where('userId',$dg->id)->where('metadata->openingReceipt->readerId',$director->id)->count();
check($ack===1,'DG receives final recipient opening receipt');
$receipt->record($c2,$director);
check(App\Models\Notification::where('relatedId',$c2->id)->where('userId',$dg->id)->where('metadata->openingReceipt->readerId',$director->id)->count()===1,'reopening sends no duplicate receipt');
$reverse=App\Models\Courrier::withoutEvents(fn()=>App\Models\Courrier::create(['type'=>'INTERNE','sens'=>'SORTANT','date_reception'=>now(),'date_enregistrement'=>now(),'objet'=>'Reverse internal simulation','expediteur'=>'Direction','destinataire'=>'DG','numero'=>uniqid('REVERSE-'),'statut'=>'ENREGISTRE','enregistre_par'=>$secretary->id,'direction'=>$unit->nom,'priorite'=>'NORMALE']));
$procedure=['id'=>'test','nom'=>'Interne','targetEntityId'=>$dgUnit->id,'phases'=>[['code'=>'ORIENTATION','label'=>'DG','hours'=>1],['code'=>'CLOTURE','label'=>'Classement','hours'=>1]]];
app(App\Services\OrganisationWorkflowService::class)->create($secretary,$reverse,$dgUnit->id,null,$procedure);
$reverseSteps=App\Models\WorkflowEtape::where('courrier_id',$reverse->id)->orderBy('ordre')->get();
check($reverseSteps->pluck('assigne_a')->take(4)->all()===[$secretary->id,$director->id,$secDG->id,$dg->id],'reverse route: direction secretary, director, DG secretary, DG');
$receipt->record($reverse,$secDG);
check(!App\Models\Notification::where('relatedId',$reverse->id)->where('metadata->openingReceipt->readerId',$secDG->id)->exists(),'DG secretary does not acknowledge the DG opening');
$receipt->record($reverse,$dg);
check(App\Models\Notification::where('relatedId',$reverse->id)->where('userId',$secretary->id)->where('metadata->openingReceipt->readerId',$dg->id)->count()===1,'direction sender receives DG opening receipt');
echo "DG ROUTING TESTS PASSED\n";
} finally {if ($existing) DB::rollBack();}
